namespace WinBoard {
 [DataContract] public class CapturePreferences {
  [DataMember] public string Folder;
  [DataMember] public bool SystemAudio=true;
  [DataMember] public bool Microphone;
  [DataMember] public bool Cursor=true;
  [DataMember] public int Fps=30;
  [DataMember] public int Bitrate=8000000;
  [DataMember] public string ScreenshotHotkey="Ctrl+Alt+A";
  [DataMember] public string RecordingHotkey="Ctrl+Alt+R";
  [DataMember] public bool HideControls=true;
  public void Normalize(){if(string.IsNullOrWhiteSpace(Folder))Folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyPictures),"WinBoard");if(Fps!=15&&Fps!=30&&Fps!=60)Fps=30;if(Bitrate!=4000000&&Bitrate!=8000000&&Bitrate!=16000000)Bitrate=8000000;try{uint m,k;CaptureHotkeys.Parse(ScreenshotHotkey,out m,out k);}catch{ScreenshotHotkey="Ctrl+Alt+A";}try{uint m,k;CaptureHotkeys.Parse(RecordingHotkey,out m,out k);}catch{RecordingHotkey="Ctrl+Alt+R";}}
  public static CapturePreferences Load(string file){try{using(var s=File.OpenRead(file)){var p=(CapturePreferences)new DataContractJsonSerializer(typeof(CapturePreferences)).ReadObject(s);p.Normalize();return p;}}catch{var p=new CapturePreferences();p.Normalize();return p;}}
  public void Save(string file){Normalize();Directory.CreateDirectory(Path.GetDirectoryName(file));string temp=file+".tmp";using(var s=File.Create(temp))new DataContractJsonSerializer(typeof(CapturePreferences)).WriteObject(s,this);if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}
 }
 public static class CaptureHotkeys {
  public static void Parse(string text,out uint modifiers,out uint key){modifiers=0;key=0;if(string.IsNullOrWhiteSpace(text))throw new ArgumentException("快捷键不能为空。");foreach(string part in text.Split('+')){string token=part.Trim().ToUpperInvariant();if(token=="CTRL"||token=="CONTROL")modifiers|=2;else if(token=="ALT")modifiers|=1;else if(token=="SHIFT")modifiers|=4;else if(token=="WIN")modifiers|=8;else{Forms.Keys parsed;if(key!=0||!Enum.TryParse<Forms.Keys>(token,true,out parsed))throw new ArgumentException("快捷键格式无效，例如 Ctrl+Alt+A 或 Ctrl+Shift+F9。");key=(uint)parsed;if(key<1||key>254||key==16||key==17||key==18||key==91||key==92||(key>=160&&key<=165))throw new ArgumentException("无效的快捷键按键。");}}if(key==0||(modifiers==0&&!(key>=112&&key<=135)&&key!=44))throw new ArgumentException("字母快捷键需要 Ctrl、Alt、Shift 或 Win 修饰键。");}
 }
