  public static Drawing.Bitmap Capture(Drawing.Rectangle rect){if(rect.Width<2||rect.Height<2)throw new ArgumentException("截图区域太小。");var image=new Drawing.Bitmap(rect.Width,rect.Height,Drawing.Imaging.PixelFormat.Format32bppArgb);try{using(var g=Drawing.Graphics.FromImage(image))g.CopyFromScreen(rect.Location,Drawing.Point.Empty,rect.Size,Drawing.CopyPixelOperation.SourceCopy);return image;}catch{image.Dispose();throw;}}
