   }catch(Exception ex){FinishCaptureRecording(null,"无法开始录屏："+ex.Message+"\n录屏需要 Windows 媒体组件和 Microsoft Visual C++ 2015–2022 x64 运行库。");}finally{if(generation==captureGeneration)captureBusy=false;}}
  void SetOrbRecording(bool active){Window orb;if(!widgetWindows.TryGetValue("control",out orb))return;var button=orbSurface.Child as Button;if(button==null)return;if(active){orbOriginal=button.Content;orbRecordLabel=new TextBlock{Text="●\n00:00",Foreground=Hex("#FF706F"),FontSize=11,TextAlignment=TextAlignment.Center,VerticalAlignment=VerticalAlignment.Center};button.Content=orbRecordLabel;}else if(orbOriginal!=null){button.Content=orbOriginal;orbOriginal=null;orbRecordLabel=null;}}
  void StopCaptureRecording(Action after){if(after!=null)captureAfterStop+=after;if(recording==null){if(captureBusy&&captureBar!=null){captureGeneration++;captureBusy=false;FinishCaptureRecording(null,null);}if(captureAfterStop!=null){var callback=captureAfterStop;captureAfterStop=null;callback();}return;}if(recording.Finishing)return;captureTime.Text="正在保存…";capturePause.IsEnabled=false;captureWatch.Stop();recording.Stop();SyncCapturePanel();}
